//go:build cgo

package embeddeddolt_test

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"os"
	"testing"

	"github.com/steveyegge/beads/backend/conformance"
)

func TestBuild09RecordB17(t *testing.T) {
	if os.Getenv("BEADS_TEST_EMBEDDED_DOLT") != "1" {
		t.Fatal("set BEADS_TEST_EMBEDDED_DOLT=1; skipped recordings are forbidden")
	}
	te := newTestEnv(t, "build09record")
	ctx := t.Context()
	fixture := newEmbeddedMetadataCASFixture(t, te, "build09record")
	cases := []struct {
		name    string
		outcome string
		run     func(*testing.T, conformance.MetadataCASFixture)
	}{
		{name: "RunMetadataCASCreatesAKeyThatWasAbsent", run: func(t *testing.T, fixture conformance.MetadataCASFixture) {
			conformance.RunMetadataCASCreatesAKeyThatWasAbsent(t, ctx, fixture)
		}},
		{name: "RunMetadataCASRefusesASecondCreateAndReportsTheHolder", run: func(t *testing.T, fixture conformance.MetadataCASFixture) {
			conformance.RunMetadataCASRefusesASecondCreateAndReportsTheHolder(t, ctx, fixture)
		}},
		{name: "RunMetadataCASSwapsOnAMatchAndReportsTheNewValue", run: func(t *testing.T, fixture conformance.MetadataCASFixture) {
			conformance.RunMetadataCASSwapsOnAMatchAndReportsTheNewValue(t, ctx, fixture)
		}},
		{name: "RunMetadataCASRefusalReportsTheCurrentValueAndWritesNothing", run: func(t *testing.T, fixture conformance.MetadataCASFixture) {
			conformance.RunMetadataCASRefusalReportsTheCurrentValueAndWritesNothing(t, ctx, fixture)
		}},
		{name: "RunMetadataCASComparesCanonically", outcome: "canonicalObjectCAS", run: func(t *testing.T, fixture conformance.MetadataCASFixture) {
			conformance.RunMetadataCASComparesCanonically(t, ctx, fixture)
		}},
		{name: "RunMetadataCASReportsTheValueTheRowHolds", run: func(t *testing.T, fixture conformance.MetadataCASFixture) {
			conformance.RunMetadataCASReportsTheValueTheRowHolds(t, ctx, fixture)
		}},
		{name: "RunMetadataCASDistinguishesAnAbsentKeyFromAStoredNull", outcome: "nullVersusAbsent", run: func(t *testing.T, fixture conformance.MetadataCASFixture) {
			conformance.RunMetadataCASDistinguishesAnAbsentKeyFromAStoredNull(t, ctx, fixture)
		}},
		{name: "RunMetadataCASRemovesTheKeyWhenTheValueIsAbsent", outcome: "removeAbsent", run: func(t *testing.T, fixture conformance.MetadataCASFixture) {
			conformance.RunMetadataCASRemovesTheKeyWhenTheValueIsAbsent(t, ctx, fixture)
		}},
		{name: "RunMetadataCASPreservesSiblingKeys", outcome: "siblingPreserved", run: func(t *testing.T, fixture conformance.MetadataCASFixture) {
			conformance.RunMetadataCASPreservesSiblingKeys(t, ctx, fixture)
		}},
		{name: "RunMetadataCASNoOpSwapWritesNothing", outcome: "noOpSwap", run: func(t *testing.T, fixture conformance.MetadataCASFixture) {
			conformance.RunMetadataCASNoOpSwapWritesNothing(t, ctx, fixture)
		}},
		{name: "RunMetadataCASRefusesAnIDOnNeitherPlane", run: func(t *testing.T, fixture conformance.MetadataCASFixture) {
			conformance.RunMetadataCASRefusesAnIDOnNeitherPlane(t, ctx, fixture)
		}},
		{name: "RunMetadataCASAWispSwapRecordsNoDurableHistory", outcome: "ephemeralMetadataCAS", run: func(t *testing.T, fixture conformance.MetadataCASFixture) {
			conformance.RunMetadataCASAWispSwapRecordsNoDurableHistory(t, ctx, fixture)
		}},
		{name: "RunMetadataCASRecordsExactlyOneHistoryEntry", outcome: "durableHistory", run: func(t *testing.T, fixture conformance.MetadataCASFixture) {
			conformance.RunMetadataCASRecordsExactlyOneHistoryEntry(t, ctx, fixture)
		}},
	}
	var mainCursor, ignoredCursor int
	if err := fixture.QueryScalar(ctx, "SELECT MAX(version) FROM schema_migrations", nil, &mainCursor); err != nil {
		t.Fatal(err)
	}
	if err := fixture.QueryScalar(ctx, "SELECT MAX(version) FROM ignored_schema_migrations", nil, &ignoredCursor); err != nil {
		t.Fatal(err)
	}
	passed := make([]string, 0, len(cases))
	outcomes := make(map[string]string)
	observations := make(map[string]any)
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			measured := fixture
			counts := []int{}
			if fixture.CountHistory == nil || fixture.CommitPending == nil {
				t.Fatal("the recorder requires observable, settled history")
			}
			measured.CountHistory = func(ctx context.Context) (int, error) {
				count, err := fixture.CountHistory(ctx)
				if err == nil {
					counts = append(counts, count)
				}
				return count, err
			}
			tc.run(t, measured)
			if t.Failed() || t.Skipped() {
				return
			}
			switch tc.outcome {
			case "ephemeralMetadataCAS":
				if len(counts) != 2 {
					t.Fatalf("ephemeral history observation count = %d", len(counts))
				}
				var durableEvents int
				if err := fixture.QueryScalar(ctx, "SELECT COUNT(*) FROM events WHERE issue_id = ?", []any{fixture.IssuePrefix + "-cas-wisphistory"}, &durableEvents); err != nil {
					t.Fatal(err)
				}
				observations[tc.outcome] = map[string]int{"historyDelta": counts[1] - counts[0], "durableEvents": durableEvents}
			case "durableHistory":
				if len(counts) != 4 {
					t.Fatalf("durable history observation count = %d", len(counts))
				}
				observations[tc.outcome] = map[string]int{"swapDelta": counts[1] - counts[0], "noOpDelta": counts[3] - counts[2]}
			}
			passed = append(passed, tc.name)
			if tc.outcome != "" {
				outcomes[tc.outcome] = "PASS"
			}
		})
	}
	if t.Failed() || len(passed) != len(cases) {
		t.Fatal("incomplete or failed reference run; no recording emitted")
	}
	vector := map[string]any{
		"card":         "B17",
		"engine":       "embedded-dolt",
		"source":       "backend/conformance/metadata_cas_contract.go",
		"tests":        passed,
		"outcomes":     outcomes,
		"observations": observations,
	}
	raw, err := json.Marshal(vector)
	if err != nil {
		t.Fatal(err)
	}
	sum := sha256.Sum256(raw)
	result := map[string]any{
		"digest":        hex.EncodeToString(sum[:]),
		"vector":        vector,
		"rawJSON":       string(raw),
		"schemaCursors": map[string]int{"mainCursor": mainCursor, "ignoredCursor": ignoredCursor},
	}
	out, err := json.MarshalIndent(result, "", "  ")
	if err != nil {
		t.Fatal(err)
	}
	out = append(out, '\n')
	if path := os.Getenv("BUILD09_RECORDER_OUTPUT"); path != "" {
		if err := os.WriteFile(path, out, 0o600); err != nil {
			t.Fatal(err)
		}
	}
	fmt.Printf("BUILD09_B17_DIGEST=%s\n", hex.EncodeToString(sum[:]))
	fmt.Printf("BUILD09_B17_VECTOR=%s\n", raw)
}
